"""Strip 'Generated by PaperCast.' from all uploaded video descriptions."""
from __future__ import annotations

import sys
from pathlib import Path

from googleapiclient.discovery import build

sys.stdout.reconfigure(encoding="utf-8")
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
from src.upload.youtube import _load_credentials  # noqa: E402

PAPERCAST_LINE = "Generated by PaperCast."


def main() -> None:
    creds = _load_credentials(None)
    yt = build("youtube", "v3", credentials=creds)

    ch = yt.channels().list(part="contentDetails", mine=True).execute()
    uploads = ch["items"][0]["contentDetails"]["relatedPlaylists"]["uploads"]

    video_ids = []
    page = None
    while True:
        r = yt.playlistItems().list(
            part="contentDetails", playlistId=uploads, maxResults=50, pageToken=page
        ).execute()
        for it in r["items"]:
            video_ids.append(it["contentDetails"]["videoId"])
        page = r.get("nextPageToken")
        if not page:
            break
    print(f"{len(video_ids)} videos found.", flush=True)

    # Batch fetch full snippet (50 at a time)
    for i in range(0, len(video_ids), 50):
        batch = video_ids[i:i + 50]
        r = yt.videos().list(part="snippet", id=",".join(batch)).execute()
        for v in r["items"]:
            sn = v["snippet"]
            desc = sn.get("description", "")
            if PAPERCAST_LINE not in desc:
                continue
            new_desc = desc.replace(PAPERCAST_LINE, "").rstrip("\n").rstrip()
            try:
                yt.videos().update(
                    part="snippet",
                    body={"id": v["id"], "snippet": {
                        "title": sn["title"],
                        "description": new_desc,
                        "categoryId": sn.get("categoryId", "28"),
                        "tags": sn.get("tags", []),
                    }},
                ).execute()
                print(f"  OK   {v['id']}  {sn['title'][:50]}")
            except Exception as e:
                print(f"  FAIL {v['id']}  {e}")


if __name__ == "__main__":
    main()
